import { extend } from '../vue'
import { PROP_TYPE_STRING } from '../constants/props'

// --- Props ---

export const props = {
  size: {
    type: PROP_TYPE_STRING,
    required: false,
    default: undefined
  }
}

// --- Mixin ---

// @vue/component
export const formSizeMixin = extend({
  props,
  computed: {
    sizeFormClass() {
      return [this.size ? `form-control-${this.size}` : null]
    }
  }
})
